(()=>{const form=document.getElementById('contactform'),dialog=document.getElementById('contact'),steps=[...form.querySelectorAll('[data-intake-step]')],next=document.getElementById('intake-next'),back=document.getElementById('intake-back'),submit=document.getElementById('intake-submit'),result=document.getElementById('contactresult');let index=0;const labels=window.BathstoreWhatsApp.labels;
function setType(){const value=form.elements.project_type.value;form.querySelectorAll('[data-project-fields]').forEach(group=>{group.disabled=group.dataset.projectFields!==value;group.hidden=group.disabled})}function contactRequirement(){const required=form.elements.contact_method.value!=='Email';form.elements.phone.required=required;document.getElementById('phone-required').textContent=required?'*':''}function summary(){const data=new FormData(form),box=document.getElementById('brief-review');box.replaceChildren();const title=document.createElement('span');title.className='eyebrow';title.textContent='YOUR PROJECT AT A GLANCE';box.append(title);const list=document.createElement('dl');for(const key of ['project_type','location','bathrooms','budget','timeline']){const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=labels[key];dd.textContent=data.get(key)||'Not specified';row.append(dt,dd);list.append(row)}box.append(list)}function show(step,focus=true){index=step;steps.forEach((panel,i)=>panel.hidden=i!==step);document.querySelectorAll('[data-intake-progress]').forEach((node,i)=>{node.classList.toggle('active',i===step);node.classList.toggle('complete',i<step);if(i===step)node.setAttribute('aria-current','step');else node.removeAttribute('aria-current')});back.hidden=step===0;next.hidden=step===2;submit.hidden=step!==2;if(step===2)summary();dialog.scrollTop=0;if(focus){const first=steps[step].querySelector('input:not(:disabled),select:not(:disabled),textarea:not(:disabled)');first?.focus({preventScroll:true})}}function validate(panel){const invalid=[...panel.querySelectorAll('input,select,textarea')].find(el=>!el.disabled&&!el.checkValidity());if(invalid){invalid.reportValidity();return false}return true}form.addEventListener('change',e=>{if(e.target.name==='project_type')setType();if(e.target.name==='contact_method')contactRequirement();result.replaceChildren()});form.addEventListener('input',()=>result.replaceChildren());next.addEventListener('click',()=>{if(validate(steps[index]))show(index+1)});back.addEventListener('click',()=>show(index-1));form.addEventListener('keydown',e=>{if(e.key==='Enter'&&index<2&&e.target.tagName!=='TEXTAREA'&&e.target.tagName!=='BUTTON'){e.preventDefault();next.click()}});
window.openProjectBrief=(context='',type='')=>{document.querySelectorAll('dialog[open]').forEach(d=>d.close());if(context&&!form.elements.vision.value)form.elements.vision.value=context;if(type){const radio=[...form.querySelectorAll('[name="project_type"]')].find(el=>el.value===type);if(radio)radio.checked=true}setType();contactRequirement();result.replaceChildren();show(0,false);dialog.showModal();steps[0].querySelector('input:checked')?.focus({preventScroll:true})};document.querySelectorAll('[data-enquiry]').forEach(button=>button.addEventListener('click',()=>window.openProjectBrief(button.dataset.enquiry)));document.querySelectorAll('[data-open-brief]').forEach(button=>button.addEventListener('click',()=>window.openProjectBrief()));document.querySelectorAll('[data-start-project]').forEach(button=>button.addEventListener('click',()=>window.openProjectBrief('',button.dataset.startProject)));
form.addEventListener('submit',event=>{event.preventDefault();setType();contactRequirement();for(let i=0;i<steps.length;i++){const invalid=[...steps[i].querySelectorAll('input,select,textarea')].find(el=>!el.disabled&&!el.checkValidity());if(invalid){show(i,false);invalid.reportValidity();return}}const text=window.BathstoreWhatsApp.message(new FormData(form));const h=document.createElement('h3');h.textContent='Ready to share your project?';const p=document.createElement('p');p.textContent='Review the message below. WhatsApp will open a chat with The Bathstore on '+window.BathstoreWhatsApp.displayRecipient+'. Tap Send there to complete your enquiry.';const preview=document.createElement('pre');preview.className='whatsapp-message-preview';preview.textContent=text;const link=document.createElement('a');link.href=window.BathstoreWhatsApp.link(text);link.target='_blank';link.rel='noopener noreferrer';link.className='button whatsapp-send';link.textContent='Send via WhatsApp';const symbol=document.createElementNS('http://www.w3.org/2000/svg','svg');symbol.setAttribute('class','ui-icon');symbol.setAttribute('viewBox','0 0 24 24');symbol.setAttribute('fill','none');symbol.setAttribute('stroke','currentColor');symbol.setAttribute('stroke-width','1.5');symbol.setAttribute('aria-hidden','true');const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d','M5 19 19 5M5 5h14v14');symbol.append(path);link.append(symbol);result.replaceChildren(h,p,preview,link);result.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'nearest'});link.focus({preventScroll:true})});setType();contactRequirement();})();
